"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

// Notification: generated by UIX from the design system. Same variants and sizes as the Figma component.

const notificationVariants = cva(
  "flex w-full items-start border-b gap-3 p-4 border-line-subtle",
  {
    variants: {
      status: {
        unread: "skin-keep bg-brand-subtle/50",
        read: "bg-surface",
      },
    },
    defaultVariants: {
      status: "unread",
    },
  },
);

export interface NotificationProps
  extends React.HTMLAttributes<HTMLElement>,
    VariantProps<typeof notificationVariants> {
  /** Avatar at the start (for example <Avatar initials="RS" />). */
  avatar?: React.ReactNode;
  name: React.ReactNode;
  /** What happened, for example "commented on". */
  action?: React.ReactNode;
  target?: React.ReactNode;
  time?: React.ReactNode;
  /** Buttons under the message (Accept / Decline). */
  actions?: React.ReactNode;
}

const Notification = React.forwardRef<HTMLElement, NotificationProps>(
  ({ className, status, avatar, name, action, target, time, actions, ...props }, ref) => (
    <article data-slot="notification" data-kind="surface" ref={ref} className={cn(notificationVariants({ status }), className)} {...props}>
      {avatar}
      <div className="flex min-w-0 flex-1 flex-col gap-1">
        <p className="flex flex-wrap gap-1">
          <span className="text-label-medium text-fg-primary">{name}</span>
          {action ? <span className="text-body-small text-fg-secondary">{action}</span> : null}
          {target ? <span className="text-label-medium text-fg-primary">{target}</span> : null}
        </p>
        {time ? <p className="text-body-xs text-fg-tertiary">{time}</p> : null}
        {actions ? <div className="flex items-center gap-2 py-1">{actions}</div> : null}
      </div>
      {(status ?? "unread") === "unread" ? <span role="img" aria-label="Unread" className="mt-1.5 shrink-0 rounded-full size-2 bg-brand" /> : null}
    </article>
  ),
);
Notification.displayName = "Notification";

export { Notification, notificationVariants };
